import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.DNWyyI0w.js";const p=JSON.parse('{"title":"Managing Runs from Chat","description":"","frontmatter":{},"headers":[],"relativePath":"guides/managing-runs.md","filePath":"guides/managing-runs.md"}'),n={name:"guides/managing-runs.md"};function s(d,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="managing-runs-from-chat" tabindex="-1">Managing Runs from Chat <a class="header-anchor" href="#managing-runs-from-chat" aria-label="Permalink to &quot;Managing Runs from Chat&quot;">​</a></h1><p>Everything the Runs UI does is also a tool PRIME can call, so you can drive a run entirely from chat.</p><h2 id="find-it" tabindex="-1">Find it <a class="header-anchor" href="#find-it" aria-label="Permalink to &quot;Find it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Use</th></tr></thead><tbody><tr><td><code>list_runs</code></td><td>Recent runs with status, project, and preview</td></tr><tr><td><code>search_runs</code></td><td>Full-text across briefs and threads</td></tr><tr><td><code>get_run</code></td><td>One run&#39;s detail — thread, checklist, participants, usage</td></tr><tr><td><code>search_activity</code></td><td>Across runs: what happened, when, by whom</td></tr></tbody></table><h2 id="steer-it" tabindex="-1">Steer it <a class="header-anchor" href="#steer-it" aria-label="Permalink to &quot;Steer it&quot;">​</a></h2><p><strong>Reply into a run</strong> with <code>reply_to_run</code>. This is how you answer an agent&#39;s question — PRIME relays it back to whoever asked, in the same session, so no context is lost.</p><p><strong>Control it</strong> with <code>control_run</code>:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><code>pause</code></td><td>Stops after the current step; fully resumable</td></tr><tr><td><code>resume</code></td><td>Picks up from where it paused</td></tr><tr><td><code>halt</code></td><td>Stops the run (<code>cancelled</code>)</td></tr><tr><td><code>reopen</code></td><td>Brings a <code>done</code>/<code>error</code>/<code>cancelled</code> run back to active</td></tr><tr><td><code>delete</code></td><td>Removes it</td></tr></tbody></table><p>Pausing is not the same as halting. A paused run keeps every participant session and branch, so resuming costs nothing but the next turn.</p><h2 id="resolve-an-approval" tabindex="-1">Resolve an approval <a class="header-anchor" href="#resolve-an-approval" aria-label="Permalink to &quot;Resolve an approval&quot;">​</a></h2><p>When a project&#39;s policy is <code>approval: confirm</code>, a write parks the run at <code>awaiting_input</code> holding a <code>PendingApproval</code> that names the target project, the exact task, and the question.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resolve_run_approval(runId, approvalId, decision: &quot;approve&quot; | &quot;deny&quot;, note?)</span></span></code></pre></div><p>Approving re-runs <strong>that exact delegation</strong> with <code>approved: true</code>. Denying records the decision and hands control back to PRIME, which will re-plan around it rather than retrying blindly.</p><div class="warning custom-block"><p class="custom-block-title">Approve the change, not the sentence</p><p>The gate is structured on purpose. A free-text &quot;yes&quot; in chat is ambiguous about <em>which</em> pending change it refers to when more than one is queued.</p></div><h2 id="read-the-evidence" tabindex="-1">Read the evidence <a class="header-anchor" href="#read-the-evidence" aria-label="Permalink to &quot;Read the evidence&quot;">​</a></h2><p>For any completed task, three things are worth checking, in this order:</p><ol><li><strong><code>verification</code></strong> — the verdict, and <code>by</code>. A <code>by: &#39;command&#39;</code> pass is a real exit code. A <code>by: &#39;model&#39;</code> pass is a second opinion on the report. <code>by: &#39;none&#39;</code> means nothing checkable was available — treat that task as unverified.</li><li><strong><code>evidenceManifest.changes</code></strong> — the branch, the base it was cut from, the commits, and per-file additions/deletions, read off git by the engine rather than reported by the agent.</li><li><strong><code>evidenceManifest.commands</code></strong> — each command, its exit code, and its output tail.</li></ol><p>The run-level <code>verificationLog</code> is the append-only record. If a task disappeared from the checklist between amendments, its verdicts are still there.</p><h2 id="watch-the-cost" tabindex="-1">Watch the cost <a class="header-anchor" href="#watch-the-cost" aria-label="Permalink to &quot;Watch the cost&quot;">​</a></h2><p><code>get_run</code> returns the <code>usageLog</code>: one entry per settled LLM call with actor, models, token counts, cost, and duration. Two flags matter when the numbers look wrong:</p><ul><li><strong><code>unpriced</code></strong> on an entry — tokens were spent but the provider never reported a price.</li><li><strong><code>unreported</code></strong> on a usage record — the call ran and <em>no</em> request reported a token. Those zeros are the absence of a measurement, not a measurement of zero.</li></ul><p>Per-message <code>stats</code> also carry <code>costShared: true</code> when a cost is this message&#39;s <em>share</em> of a turn total rather than a quoted per-call price. The UI says so rather than presenting an estimate as an invoice.</p><h2 id="hand-files-back-and-forth" tabindex="-1">Hand files back and forth <a class="header-anchor" href="#hand-files-back-and-forth" aria-label="Permalink to &quot;Hand files back and forth&quot;">​</a></h2><ul><li><code>attach_run_assets</code> — attach files an agent produced to the run.</li><li><code>send_file</code> — deliver a file to you in chat; it renders as an image or a download.</li></ul><p>Run assets live under <code>memory/runs/&lt;id&gt;/assets/</code> and are served through the run-asset endpoint.</p><h2 id="share-it" tabindex="-1">Share it <a class="header-anchor" href="#share-it" aria-label="Permalink to &quot;Share it&quot;">​</a></h2><p>A run has an owner (<code>createdBy</code>) and a <code>sharedWith</code> list. Viewers can watch the thread; steering stays with the owner and admins holding <code>runs.steerAll</code>. Admins with <code>runs.viewAll</code> see every run regardless.</p><p>See also: <a href="/docs/concepts/runs">Runs</a> · <a href="/docs/reference/orchestrator-tools">Orchestrator Tools</a></p>',28)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
